import { Component, ChangeDetectionStrategy, inject, signal } from '@angular/core';
import { Router, RouterLink } from '@angular/router';
import { BackofficeService } from '../../../../core/services/backoffice.service';

@Component({
  selector: 'app-admin-login',
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [RouterLink],
  templateUrl: './admin-login.component.html',
  styleUrl: './admin-login.component.css'
})
export class AdminLoginComponent {
  private readonly backofficeService = inject(BackofficeService);
  private readonly router = inject(Router);

  readonly username = signal<string>('Operador CBB');
  readonly role = signal<string>('Administrador RAG');
  readonly areaDefault = signal<string>('ADMISIONES');
  readonly adminKey = signal<string>('');
  readonly showPassword = signal<boolean>(false);
  readonly isLoading = signal<boolean>(false);
  readonly errorMessage = signal<string | null>(null);

  onUsernameInput(event: Event): void {
    this.username.set((event.target as HTMLInputElement).value);
  }

  onRoleChange(event: Event): void {
    const selectedRole = (event.target as HTMLSelectElement).value;
    this.role.set(selectedRole);
    if (selectedRole.includes('Admisiones')) {
      this.areaDefault.set('ADMISIONES');
    } else if (selectedRole.includes('Secretaría')) {
      this.areaDefault.set('SECRETARIA');
    } else if (selectedRole.includes('Tesorería')) {
      this.areaDefault.set('TESORERIA');
    } else {
      this.areaDefault.set('GENERAL');
    }
  }

  onKeyInput(event: Event): void {
    this.adminKey.set((event.target as HTMLInputElement).value);
    if (this.errorMessage()) {
      this.errorMessage.set(null);
    }
  }

  togglePassword(): void {
    this.showPassword.update((v) => !v);
  }

  onSubmit(event: Event): void {
    event.preventDefault();
    if (!this.adminKey().trim() || this.isLoading()) return;

    this.isLoading.set(true);
    this.errorMessage.set(null);

    this.backofficeService
      .login(this.username(), this.role(), this.areaDefault(), this.adminKey())
      .subscribe({
        next: () => {
          this.isLoading.set(false);
          this.router.navigate(['/backoffice']);
        },
        error: (err) => {
          this.isLoading.set(false);
          this.errorMessage.set(err.message || 'Credenciales inválidas.');
        }
      });
  }
}
